using QuestPDF.Fluent;
using QuestPDF.Helpers;
using QuestPDF.Infrastructure;

namespace BodegaDESAM.Services;

public sealed class EntradaPdfReportService
{
    const string Navy="#17324D", Blue="#276A93", Muted="#607080", Line="#D9E2E9", Stripe="#EDF4F8";
    public byte[] CreatePdf(Entrada e, string? registradoPor)
    {
        QuestPDF.Settings.License=LicenseType.Community;
        var unidades=e.DetalleEntrada.Sum(x=>x.Cantidad); var monto=e.DetalleEntrada.Sum(x=>x.Cantidad*(x.ValorUnitario??0));
        return Document.Create(d=>d.Page(p=>{ p.Size(PageSizes.A4); p.Margin(32); p.DefaultTextStyle(x=>x.FontFamily("Arial").FontSize(9).FontColor("#1F2933"));
            p.Header().Element(c=>Header(c,"COMPROBANTE DE ENTRADA",e.Id,"Recepción de existencias"));
            p.Content().Column(c=>{ c.Spacing(14); c.Item().Element(x=>Metadata(x,e,registradoPor)); c.Item().Element(x=>Detail(x,e)); c.Item().AlignRight().Width(230).Background("#F5F8FA").Border(1).BorderColor(Line).Padding(9).Column(x=>{ Row(x,"TOTAL DE UNIDADES",$"{unidades:N0}"); x.Item().PaddingTop(5).BorderTop(1).BorderColor(Line).PaddingTop(5).Row(r=>{r.RelativeItem().Text("VALOR TOTAL").FontSize(8).Bold().FontColor(Navy);r.AutoItem().Text($"$ {monto:N0}").FontSize(11).Bold().FontColor(Navy);});}); c.Item().Element(x=>Signatures(x,"Recibe en bodega",registradoPor,"Entrega / proveedor",e.Proveedor?.Nombre)); c.Item().Text("Este documento respalda la recepción física y el ingreso de existencias al inventario.").FontSize(7.5f).FontColor(Muted); }); p.Footer().Element(Footer); })).GeneratePdf();
    }
    static void Header(IContainer c,string title,int id,string subtitle)=>c.Column(x=>{x.Item().Background(Navy).Padding(14).Row(r=>{r.RelativeItem().Column(l=>{l.Item().Text("DESAM | GESTIÓN DE BODEGA").FontSize(9).SemiBold().FontColor("#CDE4F2");l.Item().PaddingTop(3).Text(title).FontSize(16).Bold().FontColor(Colors.White);l.Item().Text(subtitle).FontSize(8.5f).FontColor("#D7E5ED");});r.ConstantItem(120).AlignMiddle().AlignRight().Column(q=>{q.Item().Text("FOLIO").FontSize(7).SemiBold().FontColor("#CDE4F2");q.Item().Text($"N° {id:D6}").FontSize(14).Bold().FontColor(Colors.White);});});x.Item().Height(3).Background(Blue);});
    static void Metadata(IContainer c,Entrada e,string? user)=>c.Table(t=>{t.ColumnsDefinition(x=>{x.RelativeColumn();x.RelativeColumn();x.RelativeColumn();});Cell(t,"FECHA DEL MOVIMIENTO",e.Fecha.ToString("dd/MM/yyyy"));Cell(t,"DOCUMENTO DE RESPALDO",V(e.NDocumento));Cell(t,"REGISTRADO POR",V(user));Cell(t,"BODEGA",NameCode(e.Bodega?.Nombre,e.Bodega?.Codigo));Cell(t,"PROVEEDOR",V(e.Proveedor?.Nombre));Cell(t,"RUT PROVEEDOR",V(e.Proveedor?.RUT));Cell(t,"CONTACTO",V(e.Proveedor?.PersonaContacto));Cell(t,"TELÉFONO",V(e.Proveedor?.Telefono));Cell(t,"CORREO",V(e.Proveedor?.Email));Cell(t,"OBSERVACIONES",V(e.Observacion),3);});
    static void Detail(IContainer c,Entrada e)=>c.Column(x=>{x.Item().BorderLeft(3).BorderColor(Blue).PaddingLeft(7).Text("DETALLE Y TRAZABILIDAD DE LA RECEPCIÓN").FontSize(9).SemiBold().FontColor(Navy);x.Item().PaddingTop(5).Table(t=>{t.ColumnsDefinition(q=>{q.RelativeColumn(3.4f);q.RelativeColumn(3.1f);q.RelativeColumn(2.2f);});Head(t,"PRODUCTO");Head(t,"TRAZABILIDAD Y UBICACIÓN");Head(t,"CANTIDAD Y VALOR",true);var i=0;foreach(var d in e.DetalleEntrada.OrderBy(q=>q.Id)){var bg=i++%2==0?"#FFFFFF":Stripe;Body(t,bg,z=>{z.Item().Text(d.Producto?.Nombre??"Sin producto").SemiBold();z.Item().Text($"Categoría: {V(d.Producto?.CategoriaProducto?.Nombre)}").FontSize(7.5f).FontColor(Muted);z.Item().Text($"Marca / modelo: {V(d.Marca?.Nombre)} / {V(d.Modelo?.Nombre)}").FontSize(7.5f).FontColor(Muted);});Body(t,bg,z=>{z.Item().Text($"Lote: {V(d.Lote?.Codigo)}").FontSize(8);z.Item().Text($"Vencimiento: {(d.FechaVencimiento??d.Lote?.FechaVencimiento)?.ToString("dd/MM/yyyy")??"-"}").FontSize(8);z.Item().Text($"Ubicación: {V(d.Ubicacion?.CodigoCompleto)}").FontSize(8);var s=d.ProductoSeries.Where(q=>!string.IsNullOrWhiteSpace(q.Serie)).Select(q=>q.Serie.Trim());z.Item().Text($"Series: {(s.Any()?string.Join(", ",s):"-")}").FontSize(7.2f).FontColor(Muted);});Body(t,bg,z=>{z.Item().AlignRight().Text($"{d.Cantidad:N0} un.").SemiBold();z.Item().AlignRight().Text($"$ {d.ValorUnitario.GetValueOrDefault():N0} c/u").FontSize(8).FontColor(Muted);z.Item().AlignRight().Text($"$ {d.Cantidad*d.ValorUnitario.GetValueOrDefault():N0}").FontSize(9).SemiBold().FontColor(Navy);},true);}});});
    static void Signatures(IContainer c,string a,string? an,string b,string? bn)=>c.PaddingTop(8).Row(r=>{Sig(r.RelativeItem(),a,an);r.ConstantItem(42);Sig(r.RelativeItem(),b,bn);}); static void Sig(IContainer c,string role,string? name)=>c.Column(x=>{x.Item().Text(role.ToUpperInvariant()).FontSize(7.5f).SemiBold().FontColor(Muted);x.Item().Height(30).BorderBottom(1).BorderColor(Muted);x.Item().PaddingTop(4).Text(V(name)).FontSize(8).SemiBold();x.Item().Text("Nombre, firma y fecha").FontSize(7).FontColor(Muted);});
    static void Footer(IContainer c)=>c.BorderTop(1).BorderColor(Line).PaddingTop(6).Row(r=>{r.RelativeItem().Text("Sistema de Gestión de Bodega DESAM").FontSize(7.5f).FontColor(Muted);r.AutoItem().Text(t=>{t.Span("Página ").FontSize(7.5f).FontColor(Muted);t.CurrentPageNumber().FontSize(7.5f).FontColor(Muted);t.Span(" de ").FontSize(7.5f).FontColor(Muted);t.TotalPages().FontSize(7.5f).FontColor(Muted);t.Span($" | Emitido {DateTime.Now:dd/MM/yyyy HH:mm}").FontSize(7.5f).FontColor(Muted);});});
    static void Cell(TableDescriptor t,string l,string v,uint span=1)=>t.Cell().ColumnSpan(span).Border(1).BorderColor(Line).Padding(7).Column(x=>{x.Item().Text(l).FontSize(6.8f).SemiBold().FontColor(Muted);x.Item().PaddingTop(2).Text(v).FontSize(8.5f).SemiBold();}); static void Head(TableDescriptor t,string v,bool right=false){var c=t.Cell().Background(Navy).Padding(7);if(right)c=c.AlignRight();c.Text(v).FontSize(7.5f).SemiBold().FontColor(Colors.White);} static void Body(TableDescriptor t,string bg,Action<ColumnDescriptor> a,bool right=false){var c=t.Cell().Background(bg).BorderBottom(1).BorderColor(Line).Padding(7);if(right)c=c.AlignRight();c.Column(a);} static void Row(ColumnDescriptor c,string l,string v)=>c.Item().Row(r=>{r.RelativeItem().Text(l).FontSize(7.5f).FontColor(Muted);r.AutoItem().Text(v).FontSize(8.5f).SemiBold();}); static string V(string? s)=>string.IsNullOrWhiteSpace(s)?"-":s.Trim(); static string NameCode(string? n,string? code)=>string.IsNullOrWhiteSpace(code)?V(n):$"{V(n)} ({code.Trim()})";
}
